from pathlib import Path
root=Path(__file__).resolve().parent.parent
s=(root/'sprint-helper.js').read_text()
code=s[s.index('function s4tRenderMemberRows('):s.index('function s4tSprintSummary(')]
test='''const rows=Array.from({length:40},(_,i)=>({name:'Member '+i,assigned:12,completed:6,remaining:6,completionPercentage:50,cardsTotal:4,cardsCompleted:2,cardsPending:2,notSureAssigned:2,notSureCompleted:1,notSureCardsTotal:1,notSureCardsCompleted:1}));
(async()=>{let errors=[];const check=(v,m)=>{if(!v)errors.push(m)},wait=ms=>new Promise(r=>setTimeout(r,ms));s4tRenderMemberRows(rows,false);const list=document.querySelector('.s4t-members-list'),summary=document.querySelector('.s4t-summary-card');await wait(50);const top=summary.getBoundingClientRect().top;list.scrollTo({top:350,behavior:'instant'});check(list.scrollTop===350,'list can scroll');s4tRenderMemberRows(rows,true);check(list.scrollTop===350,'toggle preserves scroll');const first=list.firstElementChild;s4tRenderMemberRows(rows,true);check(first===list.firstElementChild,'unchanged rows not rebuilt');check(summary.getBoundingClientRect().top===top,'summary remains fixed');check(getComputedStyle(list).overscrollBehavior==='contain','scroll stays in popup');check(getComputedStyle(first).transitionProperty==='none','no row layout transition');document.querySelector('#result').textContent=errors.length?'FAIL: '+errors.join('; '):'PASS: scroll position, fixed summary, stable rows and contained scrolling';})();'''
html='<html><head><style>'+(root/'sprint-helper.css').read_text()+'</style></head><body><div id="s4t-modal-overlay"><div id="s4t-members-modal"><div class="s4t-modal-header">Members Burndown</div><div class="s4t-modal-body"><div class="s4t-summary-card">Team summary</div><div id="s4t-members-container" class="s4t-members-list"></div></div></div></div><pre id="result">RUNNING</pre><script>'+code+test+'</script></body></html>'
Path('/tmp/s4t-members-scroll.html').write_text(html)
